mapper.insert:
INSERT INTO INTERVIEW_QUESTION_SCORE (
	INTERVIEW_SCORE_NO
	, INTERVIEW_QUESTION_NO
	, INTERVIEW_QUESTION_SCORE
) VALUES (
	#{interviewScoreNo}
	, #{interviewQuestionNo}
	, #{interviewQuestionScore}
)

mapper.update:
UPDATE INTERVIEW_QUESTION_SCORE
SET 
	INTERVIEW_QUESTION_SCORE = #{interviewQuestionScore}
WHERE INTERVIEW_SCORE_NO = #{interviewScoreNo}
AND INTERVIEW_QUESTION_NO = #{interviewQuestionNo}

mapper.delete:
DELETE FROM INTERVIEW_QUESTION_SCORE
WHERE INTERVIEW_SCORE_NO = #{interviewScoreNo}
AND INTERVIEW_QUESTION_NO = #{interviewQuestionNo}
